        except ValueError:
            return None
    return None

kept = []

for r in range(1, max_row + 1):
    if vws is None:
        break

    v = vws.cell(row=r, column=3).value

    if v is None:
        continue

    if isinstance(v, str) and v.strip() == "":
        continue

    n = as_number(v)
    if n is not None and -1.0 <= n <= 1.0:
        continue

    if isinstance(v, str):
        kept.append(v.strip())
    else:
        kept.append(v)

for i in range(1, 8):
    if i <= len(kept):
        ws.cell(row=i, column=3, value=kept[i - 1])
    else:
        ws.cell(row=i, column=3, value=None)

wb.save(OUT)

